const keys={};let joy={x:0,y:0,active:false,pointerId:null};let cameraYaw=0,cameraPitch=.27,lastPointer=null;
const joystickDeadZone=.06;
function getMoveInput(){
  let forward=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0)-joy.y;
  let side=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+joy.x;
  const length=Math.hypot(side,forward);
  if(length>1){side/=length;forward/=length}
  return {side,forward};
}
function cameraRelativeMove(side,forward,yaw){
  // Joystick X is screen-right positive; joystick Y is screen-down positive.
  // Camera-right is (cos(yaw), -sin(yaw)) in the X/Z ground plane;
  // camera-forward is (sin(yaw), cos(yaw)). This preserves handedness at every yaw.
  return {x:Math.cos(yaw)*side+Math.sin(yaw)*forward,z:-Math.sin(yaw)*side+Math.cos(yaw)*forward};
}

